<section class="account-data"><h2><?= $t('manage_connections') ?></h2>
<?php foreach (Dilemma\Db::all('SELECT c.id,c.label,d.title FROM mcp_connections c LEFT JOIN debates d ON d.id=c.debate_id WHERE c.user_id=? AND c.revoked_at IS NULL ORDER BY c.created_at DESC LIMIT 100', [$actor['user_id']]) as $grant): ?>
